func TestDiffReportsReplacementChanges(t *testing.T){s:=memory.NewStore();ps:=NewProjectService(s,s,clock.System{},&ids.Sequence{});_,_=ps.Create(context.Background(),application.CreateProjectInput{ID:"p",Name:"P",OwnerID:"o"});svc:=NewPaletteService(s,s,s,s,clock.System{},&ids.Sequence{});a,_:=svc.Create(context.Background(),application.CreatePaletteInput{ID:"a",ProjectID:"p",Name:"a",Entries:[]application.ColorInput{{Name:"x",Hex:"#112233",Replacement:"old"}}});b,_:=svc.Create(context.Background(),application.CreatePaletteInput{ID:"b",ProjectID:"p",Name:"b",Entries:[]application.ColorInput{{Name:"x",Hex:"#112233",Replacement:"new"}}});d,e:=svc.Diff(context.Background(),a.ID,b.ID);if e!=nil{t.Fatal(e)};if len(d["changed"].([]map[string]string))!=1{t.Fatalf("replacement change missing: %#v",d)}}
